package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaDecimalContextTest {
 @Test public void gradeSixOrdinarySuppliesCoverUnitsPrecisionAndFreshContexts(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();Generator g=new Generator(new Random(295));for(String id:List.of(DecimalMeasureStories.ADD,DecimalMeasureStories.SUB)){assertTrue(pack.inGrade(id,6));var l=GlobalCurriculum.limits(pack.id,id,6);assertEquals(3,l.decimalPlaces(1));assertEquals(99,l.wholeMaximum(1));List<String> recent=new ArrayList<>();Set<String> units=new HashSet<>();Set<Integer> precision=new HashSet<>();for(int i=0;i<300;i++){Question q=g.next(id,recent,false,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=DecimalMeasureStories.read(q);assertNotNull(v);units.add(v.unit());BigDecimal x=new BigDecimal(v.first()),y=new BigDecimal(v.second());precision.add(x.scale());precision.add(y.scale());assertTrue(x.signum()>=0&&x.compareTo(BigDecimal.valueOf(100))<0);assertTrue(y.signum()>=0&&y.compareTo(BigDecimal.valueOf(100))<0);if(!v.add())assertTrue(x.compareTo(y)>=0);q.answers=new String[]{"poison"};q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of((v.add()?x.add(y):x.subtract(y)).toPlainString())).correct());assertEquals(9,HelpPlan.forQuestion(q).size());assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertEquals(Set.of("m","L","kg"),units);assertEquals(Set.of(1,2,3),precision);}}
 @Test public void contextRelationsAndBorrowingUsePublicQuantities(){for(String id:List.of(DecimalMeasureStories.ADD,DecimalMeasureStories.SUB)){Question q=DecimalMeasureStories.make(id,"10.000","0.001","kg");q.answers=new String[]{"poison"};q.expression="poison";boolean add=id.equals(DecimalMeasureStories.ADD);HelpPlan h=HelpPlan.forQuestion(q);List<String> entries=List.of(add?"add":"sub","10.000","0.001","3","1000","10000","1",add?"10001":"9999",add?"10.001":"9.999");for(int i=0;i<9;i++)assertTrue(h.step(i).accepts(entries.get(i)));assertFalse(h.step(0).accepts(add?"sub":"add"));assertTrue(new Checker().check(q,List.of(),List.of(entries.get(8))).correct());}}
 @Test public void countryMappingKeepsLegacyAndInvalidContextsCannotUseHiddenKey(){assertEquals(2,GlobalCurriculum.limits("england-primary-2021-v1",DecimalMeasureStories.ADD,4).decimalPlaces(3));assertEquals(3,GlobalCurriculum.limits("england-primary-2021-v1",DecimalMeasureStories.SUB,5).decimalPlaces(1));Checker c=new Checker();for(String prompt:List.of("물 1 L에 물 2 kg을 더 부었습니다.\n모두 몇 L인가요?","broken")){assertEquals(Checker.Status.INPUT_NEEDED,c.check(new Question(DecimalMeasureStories.ADD,prompt,"","3"),List.of(),List.of("3")).status);}Question q=DecimalMeasureStories.make(DecimalMeasureStories.SUB,"1.000","1.000","m");assertTrue(c.check(q,List.of(),List.of("0")).correct());assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("0 m")).status);}
}
